JS = r'''
const header=document.querySelector('.site-header');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;addEventListener('scroll',()=>header?.classList.toggle('scrolled',scrollY>8),{passive:true});
const toggle=document.querySelector('.menu-toggle');const nav=document.querySelector('.nav');toggle?.addEventListener('click',()=>{const open=!nav.classList.contains('open');nav.classList.toggle('open',open);toggle.setAttribute('aria-expanded',String(open));});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle?.setAttribute('aria-expanded','false')}));
if(!reduced&&'IntersectionObserver'in window){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.08,rootMargin:'0px 0px -24px 0px'});document.querySelectorAll('.reveal').forEach((el,i)=>{el.style.transitionDelay=Math.min((i%3)*40,80)+'ms';io.observe(el)});}else document.querySelectorAll('.reveal').forEach(el=>el.classList.add('visible'));
const buttons=[...document.querySelectorAll('.filter-btn')],cards=[...document.querySelectorAll('.work-card')];buttons.forEach(btn=>btn.addEventListener('click',()=>{buttons.forEach(b=>b.classList.remove('active'));btn.classList.add('active');const f=btn.dataset.filter;cards.forEach(card=>{card.style.display=(f==='Όλα'||card.dataset.category===f)?'block':'none';});}));
const lb=document.getElementById('lightbox');let lbIndex=0,lastFocus=null;function visibleOpeners(){return[...document.querySelectorAll('.work-card')].filter(c=>c.style.display!=='none').map(c=>c.querySelector('.work-open'))}function show(i){const ops=visibleOpeners();if(!ops.length||!lb)return;lbIndex=(i+ops.length)%ops.length;const b=ops[lbIndex];lb.querySelector('img').src=b.dataset.src;lb.querySelector('img').alt=b.dataset.title;lb.querySelector('figcaption').textContent=b.dataset.title+' — '+b.dataset.note;lb.hidden=false;document.body.style.overflow='hidden';lb.querySelector('.lightbox-close').focus();}document.querySelectorAll('.work-open').forEach(b=>b.addEventListener('click',()=>{lastFocus=b;show(visibleOpeners().indexOf(b));}));function closeLb(){if(!lb)return;lb.hidden=true;document.body.style.overflow='';lastFocus?.focus();}lb?.querySelector('.lightbox-close')?.addEventListener('click',closeLb);lb?.querySelector('.lightbox-prev')?.addEventListener('click',()=>show(lbIndex-1));lb?.querySelector('.lightbox-next')?.addEventListener('click',()=>show(lbIndex+1));lb?.addEventListener('click',e=>{if(e.target===lb)closeLb()});document.addEventListener('keydown',e=>{if(!lb||lb.hidden)return;if(e.key==='Escape')closeLb();if(e.key==='ArrowLeft')show(lbIndex-1);if(e.key==='ArrowRight')show(lbIndex+1);});
if(!reduced){const hero=document.querySelector('.print-composition');hero?.addEventListener('pointermove',e=>{const r=hero.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;hero.querySelectorAll('.product').forEach((el,i)=>{const d=(i+1)*7;el.style.translate=(x*d)+'px '+(y*d)+'px';});});hero?.addEventListener('pointerleave',()=>hero.querySelectorAll('.product').forEach(el=>el.style.translate='0 0'));const animateCounter=el=>{const target=parseFloat(el.dataset.count||el.textContent.replace(',','.')),dec=parseInt(el.dataset.decimals||'0',10);let start=null,dur=650;function step(ts){start??=ts;const p=Math.min((ts-start)/dur,1),eased=1-Math.pow(1-p,3),v=target*eased;el.textContent=v.toLocaleString('el-GR',{minimumFractionDigits:dec,maximumFractionDigits:dec});if(p<1)requestAnimationFrame(step)}requestAnimationFrame(step)};if('IntersectionObserver'in window){const cio=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){animateCounter(e.target);cio.unobserve(e.target)}}),{threshold:.5});document.querySelectorAll('.counter').forEach(c=>cio.observe(c));}else document.querySelectorAll('.counter').forEach(animateCounter);}
const calcEls=['calcWidth','calcHeight','calcQty','calcPrice'].map(id=>document.getElementById(id));const calcResult=document.getElementById('calcResult');function updateDtfCalc(){if(!calcResult||calcEls.some(e=>!e))return;const [w,h,q,price]=calcEls.map(e=>parseFloat(e.value||'0'));const roll=58,perRow=Math.max(1,Math.floor(roll/(w+1))),rows=Math.ceil(q/perRow),meters=Math.ceil((rows*(h+1))/100*10)/10,cost=price>0?(meters*price).toFixed(2).replace('.',',')+'€':'';calcResult.value=`Περίπου ${meters.toLocaleString('el-GR')} τρέχοντα μέτρα σε ρολό 58cm (${perRow} σχέδια ανά σειρά). ${cost?`Ενδεικτικό κόστος: ${cost}.`:''}`;}calcEls.forEach(e=>e?.addEventListener('input',updateDtfCalc));updateDtfCalc();document.getElementById('sendCalc')?.addEventListener('click',()=>{updateDtfCalc();const msg=document.querySelector('textarea[name="message"]'),service=document.querySelector('select[name="service_select"]');if(service)service.value='Στάμπες DTF με το μέτρο';if(msg)msg.value=(msg.value?msg.value+'\n\n':'')+'Υπολογιστής DTF: '+calcResult.value;document.getElementById('quote')?.scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'});});
'''

def json_ld(p,current,canon):
    local={'@context':'https://schema.org','@type':'LocalBusiness','@id':SITE+'/#business','name':'Adapt Print','url':SITE+'/','image':img['og'],'logo':SITE+'/assets/images/adaptprint-logo-header-transparent.png','description':'Ψηφιακές εκτυπώσεις, στάμπες DTF με το μέτρο, επαγγελματική ένδυση, κούπες, δώρα και διαφημιστικά είδη στον Πειραιά.','telephone':['+302112181704','+306982848330'],'email':CONTACT['email'],'priceRange':'€€','areaServed':['Πειραιάς','Αθήνα','Ελλάδα'],'hasMap':CONTACT['maps'],'geo':{'@type':'GeoCoordinates','latitude':37.944,'longitude':23.648},'address':{'@type':'PostalAddress','streetAddress':'Μακεδονίας 81','addressLocality':'Πειραιάς','postalCode':'18545','addressCountry':'GR'},'openingHoursSpecification':[{'@type':'OpeningHoursSpecification','dayOfWeek':['Monday','Wednesday','Saturday'],'opens':'10:00','closes':'15:00'},{'@type':'OpeningHoursSpecification','dayOfWeek':'Tuesday','opens':'10:00','closes':'14:00'},{'@type':'OpeningHoursSpecification','dayOfWeek':'Tuesday','opens':'17:30','closes':'21:00'},{'@type':'OpeningHoursSpecification','dayOfWeek':'Thursday','opens':'10:00','closes':'14:00'},{'@type':'OpeningHoursSpecification','dayOfWeek':'Thursday','opens':'18:00','closes':'21:00'},{'@type':'OpeningHoursSpecification','dayOfWeek':'Friday','opens':'10:00','closes':'14:00'},{'@type':'OpeningHoursSpecification','dayOfWeek':'Friday','opens':'17:30','closes':'21:00'}],'sameAs':['https://www.instagram.com/adaptprint2','https://www.tiktok.com/@adaptprint']}
    crumbs=[{'@type':'ListItem','position':1,'name':'Αρχική','item':SITE+'/'}]
    if current!='/': crumbs.append({'@type':'ListItem','position':2,'name':p['h1'],'item':canon})
    graph=[local,{'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':crumbs}]
    if p['service']: graph.append({'@context':'https://schema.org','@type':'Service','name':p['h1'],'description':p['desc'],'provider':{'@id':SITE+'/#business'},'areaServed':['Πειραιάς','Αθήνα','Ελλάδα'],'url':canon})
    if p['faqs']: graph.append({'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in p['faqs']]})
    return json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False)

def page_html(p):
    cur=current_path(p['path']); canon=SITE+cur; foot=''.join(f'<li><a href="{u}">{l}</a></li>' for u,l in NAV[:4]); breadcrumb='' if cur=='/' else f'<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Αρχική</a><span> / </span><span>{esc(p["h1"])}</span></nav>'
    return f'''<!doctype html><html lang="el"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(p['title'])}</title><meta name="description" content="{esc(p['desc'])}"><link rel="canonical" href="{canon}"><meta property="og:locale" content="el_GR"><meta property="og:type" content="website"><meta property="og:site_name" content="Adapt Print"><meta property="og:title" content="{esc(p['title'])}"><meta property="og:description" content="{esc(p['desc'])}"><meta property="og:url" content="{canon}"><meta property="og:image" content="{img['og']}"><meta name="twitter:card" content="summary_large_image"><link rel="preload" as="font" href="/assets/fonts/manrope-variable-greek.woff2" type="font/woff2" crossorigin><link rel="preload" as="font" href="/assets/fonts/manrope-variable-latin.woff2" type="font/woff2" crossorigin><link rel="preload" as="image" href="/assets/images/adaptprint-logo-header-transparent.png"><link rel="icon" type="image/png" href="/assets/images/favicon.png"><link rel="apple-touch-icon" href="/assets/images/apple-touch-icon.png"><link rel="stylesheet" href="/assets/css/styles.css"><script type="application/ld+json">{json_ld(p,cur,canon)}</script></head><body><a class="skip" href="#main">Μετάβαση στο περιεχόμενο</a><div class="topbar"><div class="topbar-inner"><span>📞 <a href="{CONTACT['phone1_href']}">{CONTACT['phone1_label']}</a></span><span>📍 {CONTACT['address']}</span><span>Στάμπες DTF · Εκτυπώσεις · Δώρα</span></div></div><header class="site-header"><div class="header-inner"><a class="logo brand-lockup" href="/" aria-label="Adapt Print - Αρχική"><img src="{img['logo']}" width="156" height="64" alt="Adapt Print"></a><button class="menu-toggle btn btn-ghost" aria-expanded="false" aria-controls="nav" type="button">Μενού</button><nav id="nav" class="nav" aria-label="Κύρια πλοήγηση">{nav(cur)}</nav><div class="header-actions"><a class="btn btn-ghost" href="{CONTACT['phone1_href']}">Καλέστε</a><a class="btn btn-primary" href="/contact-us/#quote">Προσφορά</a></div></div></header><main id="main">{breadcrumb}{p['body']}{final_cta(True) if p['legal'] else ''}</main><footer class="site-footer"><div class="footer-inner"><div><img class="footer-logo" src="{img['logo']}" width="220" height="90" alt="Adapt Print"><h2>Εκτυπώσεις με πραγματική εφαρμογή.</h2><p>DTF, UV, sublimation, ένδυση, κούπες και διαφημιστικά είδη στον Πειραιά.</p><div class="social-row"><a aria-label="Facebook" href="#">f</a><a aria-label="Instagram" href="https://www.instagram.com/adaptprint2" target="_blank" rel="noopener noreferrer">ig</a><a aria-label="TikTok" href="https://www.tiktok.com/@adaptprint" target="_blank" rel="noopener noreferrer">tt</a></div></div><div><h3>Υπηρεσίες</h3><ul>{foot}</ul></div><div><h3>Επικοινωνία</h3><ul><li><a href="{CONTACT['phone1_href']}">{CONTACT['phone1_label']}</a></li><li><a href="{CONTACT['phone2_href']}">{CONTACT['phone2_label']}</a></li><li><a href="{CONTACT['email_href']}">{CONTACT['email']}</a></li><li><a href="{CONTACT['maps']}" target="_blank" rel="noopener noreferrer">{CONTACT['address']}</a></li></ul></div><div><h3>Νομικά</h3><ul><li><a href="/terms-and-conditions/">Όροι χρήσης</a></li><li><a href="/privacy-policy/">Πολιτική απορρήτου</a></li></ul></div></div><div class="footer-bottom"><span>© 2025 Adapt Print. All rights reserved.</span><span>CMYK print system · Piraeus</span></div></footer><script src="/assets/js/main.js" defer></script></body></html>'''

def redirect_page(target):
    rel='../'+target.strip('/')+'/'
    return f'<!doctype html><html lang="el"><head><meta charset="utf-8"><meta name="robots" content="noindex,follow"><link rel="canonical" href="{SITE+target}"><meta http-equiv="refresh" content="0; url={rel}"><title>Adapt Print</title></head><body><p><a href="{rel}">Συνέχεια</a></p></body></html>'

